def compute(vars):
    debt_obligations = vars["v1"]
    total_obligations = vars["v2"]

    if total_obligations == 0:
        return None

    result = (debt_obligations / total_obligations) * 100

    return {
        "value": result,
        "trace": {
            "debt_obligations": debt_obligations,
            "total_obligations": total_obligations,
            "calculation": "v1 / v2 * 100",
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
